from pathlib import Path
import json,html
root=Path('qa/v38/plaza02');pairs=json.loads((root/'pairs.json').read_text());review=json.loads((root/'frame-review.json').read_text());metrics=json.loads((root/'performance-comparison.json').read_text())
extraMetrics=json.loads((root/'performance-recheck.json').read_text());front=json.loads((root/'front-comparison.json').read_text());
rows=''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [m['name'],round(m['baselineMedianMs'],1),round(m['candidateMedianMs'],1),f"{m['changePercent']:+.1f}%",str(m['calls']),str(m['triangles'])])+'</tr>' for m in metrics)
repeatRows=''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [m['name'],round(m['baselineMedianMs'],1),round(m['candidateMedianMs'],1),f"{m['changePercent']:+.1f}%",str(m['calls']),str(m['triangles'])])+'</tr>' for m in extraMetrics)
control=f"<p>Controllo lungo del fronte · camera identica, 72 frame: {front['rows'][0]['medianMs']:.1f} → {front['rows'][1]['medianMs']:.1f} ms ({front['changePercent']:+.2f}%). I campioni brevi restano discordanti; il +17% non si ripete nel controllo lungo. Nessuna garanzia di FPS hardware.</p>"
gallery=''.join(f'<figure><img loading="lazy" src="{html.escape(r["path"])}" alt="{html.escape(r["name"])}"><figcaption>{html.escape(r["path"])} · {r["grade"]}</figcaption></figure>' for r in review['frames'] if not any(r['path'] in [p['before'],p['after']] for p in pairs))
template='''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>HOODDINO · task 02 · confronto</title><style>
*{box-sizing:border-box}body{margin:0;background:#101317;color:#eee;font:15px system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:24px}h1{font-size:25px}p{color:#bdc5cd}button,select{background:#202933;color:white;border:1px solid #536373;border-radius:6px;padding:9px}nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap}select{flex:1}#images{position:relative;aspect-ratio:16/9;margin-top:16px;background:black}#images img{position:absolute;width:100%;height:100%;object-fit:contain}#after{clip-path:inset(0 0 0 50%)}#slider{width:100%;margin:14px 0}#note{min-height:44px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:8px;border-bottom:1px solid #36424d}#gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}figure{margin:0}figure img{width:100%}figcaption{font-size:11px;color:#bdc5cd;overflow-wrap:anywhere}details{margin:24px 0}summary{cursor:pointer;padding:12px;background:#202933}
</style><main><h1>Task 02 · infissi e costo piazza</h1><p>Confronto con la main b250daf. Stesse geometrie, materiali e istanze; cambia il raggruppamento per il culling. UI nascosta, viewport 640×360, scala interna 0.6. Tempi SwiftShader relativi, nessuna misura di FPS su hardware reale.</p><nav><button id="prev">←</button><select id="view"></select><button id="next">→</button></nav><div id="images"><img id="before" alt="Prima"><img id="after" alt="Dopo"></div><input id="slider" type="range" min="0" max="100" value="50" aria-label="Confronto prima dopo"><p>Prima a sinistra · dopo a destra</p><p id="note"></p><details open><summary>Costo relativo · millisecondi per frame software</summary><p>Prima coorte · 10 ottobre</p><table><thead><tr><th>Vista</th><th>Prima</th><th>Dopo</th><th>Delta</th><th>Draw prima/dopo</th><th>Triangoli prima/dopo</th></tr></thead><tbody>METRICS</tbody></table><p>Ripetizione del percorso · 11 ottobre</p><table><thead><tr><th>Vista</th><th>Prima</th><th>Dopo</th><th>Delta</th><th>Draw prima/dopo</th><th>Triangoli prima/dopo</th></tr></thead><tbody>REPEAT</tbody></table>CONTROL</details><details><summary>Altri tier e diagnostico</summary><div id="gallery">GALLERY</div></details></main><script>
const pairs=PAIRS;const grades=GRADES;const select=document.getElementById('view');
pairs.forEach((p,i)=>{const o=document.createElement('option');o.value=i;o.textContent=p.n+' · '+p.name+' · '+p.tier;select.append(o)});
function show(){const p=pairs[Number(select.value)];document.getElementById('before').src=p.before;document.getElementById('after').src=p.after;const r=grades.frames.find(r=>r.path===p.after);document.getElementById('note').textContent='Voto '+r.grade+' · '+r.causes.join(' · ')}
select.onchange=show;document.getElementById('next').onclick=()=>{select.value=(Number(select.value)+1)%pairs.length;show()};document.getElementById('prev').onclick=()=>{select.value=(Number(select.value)+pairs.length-1)%pairs.length;show()};document.getElementById('slider').oninput=e=>{document.getElementById('after').style.clipPath='inset(0 0 0 '+e.target.value+'%)'};show();
</script></html>'''
(root/'index.html').write_text(template.replace('METRICS',rows).replace('REPEAT',repeatRows).replace('CONTROL',control).replace('GALLERY',gallery).replace('PAIRS',json.dumps(pairs)).replace('GRADES',json.dumps(review,ensure_ascii=False)))
print('Viewer:',len(pairs),'pairs; additional frames',len(review['frames'])-2*len(pairs))
